window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-94cf21cdf6deb4c4"]={"versions": [{"id": "FIG-94cf21cdf6deb4c4", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur statischen Metamodell-Struktur des AUTOSAR System Templates. Das Diagramm spezifiziert das absolut terminierte Sende-Timing (<code>Fibex4FlexRay:AbsolutelyScheduledTiming</code>) für FlexRay-Kommunikation im Kontext der Core-Communication- und FIBEX-Imports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>CoreCommunication::FrameTriggering</code>: Abstrakte Basisklasse mit Stereotyp <code>«Identifiable»</code>.\n</li><li><code>FlexrayFrameTriggering</code>: Spezialisierung von <code>FrameTriggering</code>; besitzt das Attribut <code>+ payloadPreambleIndicator: Boolean</code>. Komponiert über die Rolle <code>+absolutelyScheduledTiming</code> mit Kardinalität <code>0..*</code> Instanzen von <code>AbsolutelyScheduledTiming</code>.\n</li><li><code>AbsolutelyScheduledTiming</code>: Spezifiziert ein statisches Timing mit dem Attribut <code>+ slotID: Int</code>. Besitzt über Komposition eine 1:1-Relation <code>+communicationCycle 1</code> zu <code>Fibex4Flexray::CommunicationCycle</code>.\n</li><li><code>Fibex4Flexray::CommunicationCycle</code>: Abstrakte Basisklasse für die Zyklusdefinition.\n</li><li><code>Fibex4Flexray::CycleCounter</code>: Spezialisierung von <code>CommunicationCycle</code> mit Attribut <code>+ CycleCounter: Int</code>.\n</li><li><code>Fibex4Flexray::CycleRepetition</code>: Spezialisierung von <code>CommunicationCycle</code> mit den Attributen <code>+ BaseCycle: Int</code> und <code>+ CycleRepetition: CycleRepetitionType</code>.\n</li><li><code>Fibex4Flexray::CycleRepetitionType</code>: Enumeration mit den Werten <code>cycleRepetition1</code>, <code>cycleRepetition2</code>, <code>cycleRepetition4</code>, <code>cycleRepetition8</code>, <code>cycleRepetition16</code>, <code>cycleRepetition32</code> und <code>cycleRepetition64</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Diagramm ohne Verhaltens- oder Sequenzpfade. Zur Laufzeit bzw. Konfigurationszeit legt ein <code>FlexrayFrameTriggering</code> fest, in welchen Slots (<code>slotID</code>) und in welchen Kommunikationszyklen (entweder diskreter Einzelzyklus via <code>CycleCounter</code> oder periodisches Zyklusmuster via <code>BaseCycle</code> und 2er-Potenz-Repetition <code>CycleRepetition</code>) ein FlexRay-Frame auf dem Kommunikationskanal übertragen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfiguratoren und Generatoren müssen bei der Parametrierung von FlexRay-Clustern die Zyklusfilterung entweder als exakten Zykluswert (<code>CycleCounter</code>) oder als Wiederholungsmuster (<code>BaseCycle</code> modulo Wiederholungsbasis aus <code>CycleRepetitionType</code>) abbilden. Das Attribut <code>slotID</code> bestimmt den statischen oder dynamischen FlexRay-Slot innerhalb des Kommunikationszyklus.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cc22b020d3033b9c", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur statischen Metamodell-Struktur des AUTOSAR System Templates. Das Diagramm spezifiziert das absolut terminierte Sende-Timing (<code>Fibex4FlexRay:AbsolutelyScheduledTiming</code>) für FlexRay-Kommunikation im Kontext der Core-Communication- und FIBEX-Imports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>CoreCommunication::FrameTriggering</code>: Abstrakte Basisklasse mit Stereotyp <code>«Identifiable»</code>.\n</li><li><code>FlexrayFrameTriggering</code>: Spezialisierung von <code>FrameTriggering</code>; besitzt das Attribut <code>+ payloadPreambleIndicator: Boolean</code>. Komponiert über die Rolle <code>+absolutelyScheduledTiming</code> mit Kardinalität <code>0..*</code> Instanzen von <code>AbsolutelyScheduledTiming</code>.\n</li><li><code>AbsolutelyScheduledTiming</code>: Spezifiziert ein statisches Timing mit dem Attribut <code>+ slotID: Int</code>. Besitzt über Komposition eine 1:1-Relation <code>+communicationCycle 1</code> zu <code>Fibex4Flexray::CommunicationCycle</code>.\n</li><li><code>Fibex4Flexray::CommunicationCycle</code>: Abstrakte Basisklasse für die Zyklusdefinition.\n</li><li><code>Fibex4Flexray::CycleCounter</code>: Spezialisierung von <code>CommunicationCycle</code> mit Attribut <code>+ CycleCounter: Int</code>.\n</li><li><code>Fibex4Flexray::CycleRepetition</code>: Spezialisierung von <code>CommunicationCycle</code> mit den Attributen <code>+ BaseCycle: Int</code> und <code>+ CycleRepetition: CycleRepetitionType</code>.\n</li><li><code>Fibex4Flexray::CycleRepetitionType</code>: Enumeration mit den Werten <code>cycleRepetition1</code>, <code>cycleRepetition2</code>, <code>cycleRepetition4</code>, <code>cycleRepetition8</code>, <code>cycleRepetition16</code>, <code>cycleRepetition32</code> und <code>cycleRepetition64</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Diagramm ohne Verhaltens- oder Sequenzpfade. Zur Laufzeit bzw. Konfigurationszeit legt ein <code>FlexrayFrameTriggering</code> fest, in welchen Slots (<code>slotID</code>) und in welchen Kommunikationszyklen (entweder diskreter Einzelzyklus via <code>CycleCounter</code> oder periodisches Zyklusmuster via <code>BaseCycle</code> und 2er-Potenz-Repetition <code>CycleRepetition</code>) ein FlexRay-Frame auf dem Kommunikationskanal übertragen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfiguratoren und Generatoren müssen bei der Parametrierung von FlexRay-Clustern die Zyklusfilterung entweder als exakten Zykluswert (<code>CycleCounter</code>) oder als Wiederholungsmuster (<code>BaseCycle</code> modulo Wiederholungsbasis aus <code>CycleRepetitionType</code>) abbilden. Das Attribut <code>slotID</code> bestimmt den statischen oder dynamischen FlexRay-Slot innerhalb des Kommunikationszyklus.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c812a166bccf717d", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur statischen Metamodell-Struktur des AUTOSAR System Templates. Das Diagramm spezifiziert das absolut terminierte Sende-Timing (<code>Fibex4FlexRay:AbsolutelyScheduledTiming</code>) für FlexRay-Kommunikation im Kontext der Core-Communication- und FIBEX-Imports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>CoreCommunication::FrameTriggering</code>: Abstrakte Basisklasse mit Stereotyp <code>«Identifiable»</code>.\n</li><li><code>FlexrayFrameTriggering</code>: Spezialisierung von <code>FrameTriggering</code>; besitzt das Attribut <code>+ payloadPreambleIndicator :Boolean</code>. Komponiert über die Rolle <code>+absolutelyScheduledTiming</code> mit Kardinalität <code>0..*</code> Instanzen von <code>AbsolutelyScheduledTiming</code>.\n</li><li><code>AbsolutelyScheduledTiming</code>: Spezifiziert ein statisches Timing mit dem Attribut <code>+ slotID :Integer</code>. Besitzt über Komposition eine 1:1-Relation <code>+communicationCycle 1</code> zu <code>Fibex4Flexray::CommunicationCycle</code>.\n</li><li><code>Fibex4Flexray::CommunicationCycle</code>: Abstrakte Basisklasse für die Zyklusdefinition.\n</li><li><code>Fibex4Flexray::CycleCounter</code>: Spezialisierung von <code>CommunicationCycle</code> mit Attribut <code>+ CycleCounter :Integer</code>.\n</li><li><code>Fibex4Flexray::CycleRepetition</code>: Spezialisierung von <code>CommunicationCycle</code> mit den Attributen <code>+ BaseCycle :Integer</code> und <code>+ CycleRepetition :CycleRepetitionType</code>.\n</li><li><code>Fibex4Flexray::CycleRepetitionType</code>: Enumeration mit den Werten <code>cycleRepetition1</code>, <code>cycleRepetition2</code>, <code>cycleRepetition4</code>, <code>cycleRepetition8</code>, <code>cycleRepetition16</code>, <code>cycleRepetition32</code> und <code>cycleRepetition64</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Diagramm ohne Verhaltens- oder Sequenzpfade. Zur Laufzeit bzw. Konfigurationszeit legt ein <code>FlexrayFrameTriggering</code> fest, in welchen Slots (<code>slotID</code>) und in welchen Kommunikationszyklen (entweder diskreter Einzelzyklus via <code>CycleCounter</code> oder periodisches Zyklusmuster via <code>BaseCycle</code> und 2er-Potenz-Repetition <code>CycleRepetition</code>) ein FlexRay-Frame auf dem Kommunikationskanal übertragen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfiguratoren und Generatoren müssen bei der Parametrierung von FlexRay-Clustern die Zyklusfilterung entweder als exakten Zykluswert (<code>CycleCounter</code>) oder als Wiederholungsmuster (<code>BaseCycle</code> modulo Wiederholungsbasis aus <code>CycleRepetitionType</code>) abbilden. Das Attribut <code>slotID</code> bestimmt den statischen oder dynamischen FlexRay-Slot innerhalb des Kommunikationszyklus.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-94cf21cdf6deb4c4", "to": "FIG-cc22b020d3033b9c", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cc22b020d3033b9c", "to": "FIG-c812a166bccf717d", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>AbsolutelyScheduledTiming</code>: Datentyp des Attributs <code>slotID</code> von <code>Int</code> zu <code>Integer</code> geändert.\n</li><li><code>Fibex4Flexray::CycleCounter</code>: Datentyp des Attributs <code>CycleCounter</code> von <code>Int</code> zu <code>Integer</code> geändert.\n</li><li><code>Fibex4Flexray::CycleRepetition</code>: Datentyp des Attributs <code>BaseCycle</code> von <code>Int</code> zu <code>Integer</code> geändert.\n</li><li><code>Fibex4Flexray::CycleRepetitionType</code>: Positionierung des Stereotyps <code>«enumeration»</code> und Paketnamens im Klassenkopf redaktionell angepasst.\n</li><li>Assoziation <code>+absolutelyScheduledTiming</code>: Leerzeichen vor der Multiplizität redaktionell eingefügt (<code>0..*</code>).\n</li></ul>"}]};
